#!/usr/bin/env python3
#
#  ac_config_compiler.py - AirCycler firmware NVS config variables compiler
#
#  given a definition file Config.yaml that defines all config variables,
#  their types, NVS storage keys and default values, generate C interfaces
#  to simplify getting and setting and initializing a blank NVS.
#
#  generated files match the base name of config file minus extension
#     Config.h - #include for client code that declares all the getters and setters
#     Config.c - implementation
#

import argparse
import os
import sys

# we get PyYAML for free with esp-idf
import yaml

parser = argparse.ArgumentParser(description = 'Send command to G3')
parser.add_argument('-n', dest='no_output', action='store_const',
					const=True, default=False,
					help='skip writing output files')
parser.add_argument('-desc', dest='desc_file',
					help='write configvar descriptions to file')
parser.add_argument('-v', dest='verbose', action='append_const', const=True,
					help='verbose operation (can repeat)')
parser.add_argument('args', metavar='Args', type=str, nargs='*',
					help='source filename')
args = parser.parse_args()
verbose = len(args.verbose) if args.verbose else 0

#
#  NVType for each of the base NVS storage types
#
class NVType:
	def __init__(self, name, ctype):
		self.name = name
		self.ctype = ctype

nv_types = {
	'I8'    : NVType('I8', 'int8_t'),
	'U8'    : NVType('U8', 'uint8_t'),
	'I16'   : NVType('I16', 'int16_t'),
	'U16'   : NVType('U16', 'uint16_t'),
	'I32'   : NVType('I32', 'int32_t'),
	'U32'   : NVType('U32', 'uint32_t'),
	'I64'   : NVType('I64', 'int64_t'),
	'U64'   : NVType('U64', 'uint64_t'),
	'STRING' : NVType('STRING', None),
	'BLOB'  : NVType('BLOB', None)
}

class Configspec:
	def __init__(self):
		self.cfgfile = None
		self.namespaces = set()
		self.cannamespaces = set()
		self.configs = {}
		self.canconfigs = set()
		self.nskeys = set()         # used to detect collisions
		self.errors = []

	def add_namespace(self, ns):
		if ns.lower() in self.cannamespaces:
			self.errors.append('Attempt to redefine namespace "{0}"'.format(ns))
		elif len(ns) > 15:
			self.errors.append('Namespace "{0}" too long (maximum 15 characters)'.format(ns))
		else:
			self.namespaces.add(ns)
			self.cannamespaces.add(ns.lower())

	def add_config(self, cfg):
		if cfg.name:
			if cfg.name.lower() in self.canconfigs:
				self.errors.append('Attempt to redefine config "{0}"'.format(cfg.name))
			else:
				self.canconfigs.add(cfg.name.lower())
		nskey = (cfg.namespace, cfg.key)
		if nskey in self.nskeys:
			self.errors.append('Config "{0}" reuses NVS namespace and key {1}:{2}'.format(cfg.name, cfg.namespace, cfg.key))
		else:
			self.configs[cfg.name] = cfg
			self.nskeys.add(nskey)

	def validate(self):
		self.any_cached = False
		for cn in self.configs:
			c = self.configs[cn]
			if c.cached:
				self.any_cached = True
			if c.namespace and c.namespace not in self.namespaces:
				self.errors.append('Attempt to define config "{0}" with unknown namespace "{1}"'.format(c.name, c.namespace))
			c.validate(self.errors)
		if len(self.errors) > 0:
			sys.stderr.write('Validation errors:\n')
			for e in self.errors:
				sys.stderr.write(e + '\n')
			return False
		return True

	def generate_c_header(self, fname):
		ifdefname = fname.upper().translate(str.maketrans('./','__'))
		program = sys.executable
		with open(fname, 'w') as ff:
			ff.write(
f'''#ifndef {ifdefname}
#define {ifdefname}

/*
 * GENERATED FILE - DO NOT EDIT
 * Generated from: {cfgfile}
 * Generated by: {program}
 */

#ifdef __cplusplus
extern "C" {{
#endif

#include <stddef.h>
#include <stdint.h>
#include <esp_err.h>

/*
 * Namespaces:
 */

'''
			)

			for n in sorted(self.namespaces):
				sym = namespace_symbol_name(n)
				ff.write(
f'''#define {sym} "{n}"
'''
				)
			for n in sorted(self.namespaces):
				ff.write(
f'''
/*
 * Namespace {n} keys:
 */
'''
				)
				for cn in self.configs:
					c = self.configs[cn]
					if not c.hidden and c.namespace == n:
						sym = key_symbol_name(c.name)
						ff.write(
f'''#define {sym} "{c.key}"
'''
						)
						if c.c_type == 'string_c':
							ff.write(
f'''#define {size_symbol_name(c.name)} {c.maxsize}
'''
							)
			if self.any_cached:  # if there are any cached configvars
				ff.write(
'''
/*
 * Configvar cache indices
 */

enum {
'''
				)
				for n in sorted(self.namespaces):
					for cn in self.configs:
						c = self.configs[cn]
						if not c.hidden and c.namespace == n and c.cached:
							ff.write(
f'''    {enum_symbol_name(c.name)},
'''
							)

				ff.write(
'''    NUM_CACHED_CONFIGVARS
};
'''
				)

			ff.write('\n')
			for n in sorted(self.namespaces):
				for cn in self.configs:
					c = self.configs[cn]
					if not c.hidden and c.namespace == n:
						c.generate_c_decl(ff)

			ff.write(
f'''
/*
 * Verify NVS contents and initialize if necessary
 */
esp_err_t config_init();

#ifdef __cplusplus
}}
#endif

#endif /*{ifdefname}*/
'''
			)

	def generate_c_impl(self, fname, hname):
		hname = os.path.basename(hname)
		program = sys.executable
		with open(fname, 'w') as ff:
			ff.write(
f'''/*
 * GENERATED FILE - DO NOT EDIT
 * Generated from: {cfgfile}
 * Generated by: {program}
 */

#include "{hname}"
#include "AC_NVS.h"
#include <esp_log.h>
#include <string.h>

static const char *LOGTAG __attribute__((unused)) = "CONFIG";
'''
			)

			if self.any_cached:  # if there are any cached configvars
				ff.write(
'''
static uint8_t configvar_cache_flags[(NUM_CACHED_CONFIGVARS+7)/8] = { 0 };
#define TEST_CACHED(n) (configvar_cache_flags[(n)/8] & (1<<((n)&7)))
#define SET_CACHED(n) (configvar_cache_flags[(n)/8] |= (1<<((n)&7)))
'''
				)
			for n in sorted(self.namespaces):
				ff.write(
f'''
/*
 * Namespace {n}:
 */
'''
				)
				for cn in self.configs:
					c = self.configs[cn]
					if not c.hidden and c.namespace == n:
						#sym = key_symbol_name(c.key)
						ff.write('\n')
						c.generate_c_impl(ff)

			ff.write(
'''
esp_err_t config_init()
{
  memset(configvar_cache_flags, 0, sizeof(configvar_cache_flags));
'''
			)
			for n in sorted(self.namespaces):
				ff.write(
f'''
  {{
    const char *namespace = "{n}";
    nvs_handle_t handle;
    esp_err_t err = nvs_open(namespace, NVS_READWRITE, &handle);
    if (err != ESP_OK) {{
      ESP_LOGE(LOGTAG, "Open namespace %s failed: %d", namespace, err);
    }} else {{
      uint8_t changes = 0;
'''
				)
				for cn in self.configs:
					c = self.configs[cn]
					if not c.hidden and c.namespace == n:
						c.generate_c_init(ff)
				ff.write(
'''
      if (changes)
        nvs_commit(handle);
      nvs_close(handle);
    }
  }
'''
				)
			ff.write(
'''  return ESP_OK;
}
'''
			)

	def generate_descriptions(self, file):
		print('write descriptions to {0}'.format(file))
		with open(file, 'w') as ff:
			for cn in self.configs:
				c = self.configs[cn]
				c.generate_description(ff)

class Configvar:
	def __init__(self, name):
		self.name = name
		self.key = None
		self.namespace = None
		self.c_type = None
		self.nv_type = None
		self.default = None
		self.stringy = False
		self.maxsize = None
		self.description = None
		self.hidden = False
		self.cached = False

	def set_key(self, key):
		self.key = key

	def set_namespace(self, ns):
		self.namespace = ns

	def set_c_type(self, c_type):
		self.c_type = c_type
		if c_type and 'char' in c_type and '*' in c_type:
			self.stringy = True

	def set_nv_type(self, nv_type):
		self.nv_type = nv_type

	def set_maxsize(self, val):
		self.maxsize = val

	def set_description(self, val):
		self.description = val

	def set_default(self, val):
		self.default = val

	def set_deprecated(self, val):
		self.deprecated = val
		if val:
			self.hidden = True

	def set_cached(self, val):
		self.cached = val

	def validate(self, errors):
		if self.name == None:
			errors.append('Configvar with no name')
			return False
		e = False
		for a in ('key', 'namespace', 'c_type', 'nv_type', 'default'):
			#print('validate {0} {1} {2}'.format(self.name, a, getattr(self, a)))
			if getattr(self, a) == None:
				errors.append('Configvar "{0}" is missing {1}'.format(self.name, a))
				e = True
		if e:
			return False
		if len(self.key) > 15:
			errors.append('Configvar "{0}" key "{1}" too long (maximum 15 characters)'.format(self.name, self.key))
			return False
		if self.nv_type not in nv_types:
			errors.append('Attempt to define config "{0}" with unknown NV type "{1}"'.format(self.name, self.nv_type))
			return False
		if self.c_type == 'string_c':
			if self.nv_type != 'STRING':
				errors.append('Configvar "{0}" has conflicting types {1}/{2}'.format(self.name, self.c_type, self.nv_type))
			if not self.maxsize:
				errors.append('Configvar "{0}" with type cached string missing maxlength'.format(self.name))
		elif self.c_type == 'string':
			if self.nv_type not in ('STRING', 'BLOB'):
				errors.append('Configvar "{0}" has conflicting types {1}/{2}'.format(self.name, self.c_type, self.nv_type))
		elif self.c_type == 'void':
			if self.nv_type != 'BLOB':
				errors.append('Configvar "{0}" has conflicting types {1}/{2}'.format(self.name, self.c_type, self.nv_type))
		else:
			if self.nv_type not in ('I8', 'U8', 'I16', 'U16', 'I32', 'U32', 'I64', 'U64'):
				errors.append('Configvar "{0}" has conflicting types {1}/{2}'.format(self.name, self.c_type, self.nv_type))
			if not self.default or self.default == '':
				errors.append('Configvar "{0}" with type {1}/{2} missing default value'.format(self.name, self.c_type, self.nv_type))

	def generate_c_decl(self, ff):
		if self.c_type == 'string_c':
			c_type = 'const char *'
			ff.write(
f'''{c_type} config_get_{self.name}();
esp_err_t config_set_{self.name}({c_type});
'''
			)
		elif self.c_type == 'string':
			ff.write(
f'''esp_err_t config_get_{self.name}(char *, size_t);
esp_err_t config_set_{self.name}(const char *);
size_t config_length_{self.name}();
'''
			)
		elif self.c_type == 'void':
			ff.write(
f'''esp_err_t config_get_{self.name}(void *, size_t *);
esp_err_t config_set_{self.name}(const void *, size_t);
'''
			)
		else:
			ff.write(
f'''{self.c_type} config_get_{self.name}();
void config_set_{self.name}({self.c_type});
'''
			)

	def generate_c_impl(self, ff):
		ff.write(
f'''/*
 * Config variable: {self.name}
 */
'''
		)
		nss = namespace_symbol_name(self.namespace)
		key = key_symbol_name(self.name)
		if self.c_type == 'string_c':
			c_type = 'const char *'
			cvar = f'''config_val_{self.name}'''
			maxsize = size_symbol_name(self.name)
			defval = self.default or ''
			if self.cached:
				ff.write(
f'''static char {cvar}[{maxsize}] = {{0}};
{c_type} config_get_{self.name}()
{{
  if (!TEST_CACHED({enum_symbol_name(self.name)})) {{
    if (read_nvs_string({nss}, {key}, {cvar}, {maxsize}) != ESP_OK)
      strcpy({cvar}, "{defval}");
    SET_CACHED({enum_symbol_name(self.name)});
  }}
  return {cvar};
}}
esp_err_t config_set_{self.name}({c_type} v)
{{
  if (strlen(v) >= {maxsize})
    return ESP_ERR_INVALID_SIZE;
  strcpy({cvar}, v);
  SET_CACHED({enum_symbol_name(self.name)});
  return save_nvs_string({nss}, {key}, {cvar});
}}
'''
				)
			else:
				ff.write(
f'''static char {cvar}[{maxsize}] = {{0}};
{c_type} config_get_{self.name}()
{{
  if (read_nvs_string({nss}, {key}, {cvar}, {maxsize}) != ESP_OK)
    strcpy({cvar}, "{defval}");
  return {cvar};
}}
esp_err_t config_set_{self.name}({c_type} v)
{{
  if (strlen(v) >= {maxsize})
    return ESP_ERR_INVALID_SIZE;
  strcpy({cvar}, v);
  return save_nvs_string({nss}, {key}, {cvar});
}}
'''
				)
		elif self.c_type == 'string' and self.nv_type == 'STRING':
			ff.write(
f'''esp_err_t config_get_{self.name}(char *val, size_t maxlen)
{{
  return read_nvs_string({nss}, {key}, val, maxlen);
}}
esp_err_t config_set_{self.name}(const char *val)
{{
  return save_nvs_string({nss}, {key}, val);
}}
size_t config_length_{self.name}()
{{
  size_t len = 0;
  read_nvs_blob({nss}, {key}, NULL, &len);
  return len;
}}
'''
			)
		elif self.c_type == 'string' and self.nv_type == 'BLOB':
			ff.write(
f'''esp_err_t config_get_{self.name}(char *val, size_t maxlen)
{{
  return read_nvs_blob({nss}, {key}, val, &maxlen);
}}
esp_err_t config_set_{self.name}(const char *val)
{{
  return save_nvs_blob({nss}, {key}, val, strlen(val) + 1);
}}
size_t config_length_{self.name}()
{{
  size_t len = 0;
  read_nvs_blob({nss}, {key}, NULL, &len);
  return len;
}}
'''
			)
		elif self.c_type == 'void':
			ff.write(
f'''esp_err_t config_get_{self.name}(void *val, size_t *length)
{{
  return read_nvs_blob({nss}, {key}, val, length);
}}
esp_err_t config_set_{self.name}(const void *val, size_t length)
{{
  return save_nvs_blob({nss}, {key}, val, length);
}}
'''
			)
		else:
			defval = self.default or '0'
			if self.cached:
				# TODO: the _set_ method could compare value and avoid NV write
				cvar = f'''config_val_{self.name}'''
				ff.write(
f'''static {self.c_type} {cvar};
{self.c_type} config_get_{self.name}()
{{
  if (!TEST_CACHED({enum_symbol_name(self.name)})) {{
    {cvar} = ({self.c_type})read_nvs_{self.nv_type.lower()}({nss}, {key}, {defval});
    SET_CACHED({enum_symbol_name(self.name)});
  }}
  return {cvar};
}}
void config_set_{self.name}({self.c_type} v)
{{
  {cvar} = v;
  SET_CACHED({enum_symbol_name(self.name)});
  save_nvs_{self.nv_type.lower()}({nss}, {key},({nv_types[self.nv_type].ctype})v);
}}
'''
				)
			else:
				ff.write(
f'''{self.c_type} config_get_{self.name}()
{{
  return ({self.c_type})read_nvs_{self.nv_type.lower()}({nss}, {key}, {defval});
}}
void config_set_{self.name}({self.c_type} v)
{{
  save_nvs_{self.nv_type.lower()}({nss}, {key},({nv_types[self.nv_type].ctype})v);
}}
'''
				)

	def generate_c_init(self, ff):
		key = key_symbol_name(self.name)
		if self.c_type == 'string_c':
			maxsize = size_symbol_name(self.name)
			defval = self.default or ''
			ff.write(
f'''      if (test_create_nvs_string(handle, {key}, {maxsize}, "{defval}") != ESP_OK) changes = 1;
'''
			)
		elif self.c_type == 'string' and self.nv_type == 'STRING':
			defval = self.default or ''
			ff.write(
f'''      if (test_create_nvs_string(handle, {key}, 0, "{defval}") != ESP_OK) changes = 1;
'''
			)
		elif self.c_type == 'string' and self.nv_type == 'BLOB':
			defval = self.default or ''
			ff.write(
f'''      if (test_create_nvs_blob(handle, {key}, 0, "{defval}", strlen("{defval}") + 1) != ESP_OK) changes = 1;
'''
			)
		elif self.c_type == 'void':
			ff.write(
f'''      if (test_create_nvs_blob(handle, {key}, 0, "", 0) != ESP_OK) changes = 1;
'''
			)
		else:
			defval = self.default or '0'
			ff.write(
f'''      if (test_create_nvs_{self.nv_type.lower()}(handle, {key}, {defval}) != ESP_OK) changes = 1;
'''
			)

	def generate_description(self, ff):
		ff.write(
f'''{self.name} {self.c_type} {self.nv_type} {self.namespace}::{self.key} {self.cached} {self.default}
'''
		)
		if (self.description):
			ff.write(
f'''   {self.description}
'''
			)
		ff.write('\n')

print('AC Configvar Compiler')
print('Directory {0}'.format(os.getcwd()))

if len(args.args) != 1:
	if len(args.args) == 0:
		sys.stderr.write('Missing input file\n')
	else:
		sys.stderr.write('Can only specify one input file\n')
	sys.exit(1)

cfgfile = args.args[0]
print('Config file: {0}'.format(cfgfile))

path, file = os.path.split(cfgfile)
base, ext = os.path.splitext(file)

gencfile = os.path.join(path, base + '.c')
genhfile = os.path.join(path, base + '.h')
print('Output: {0} {1}'.format(gencfile, genhfile))

def namespace_symbol_name(n):
	return 'CONFIG_NAMESPACE_' + n.upper()

def key_symbol_name(n):
	return 'CONFIG_' + n.upper() + '_KEY'

def size_symbol_name(n):
	return 'CONFIG_' + n.upper() + '_MAXSIZE'

def enum_symbol_name(n):
	return 'CONFIG_' + n.upper() + '_INDEX'

def read_config_file(fname, spec = None):
	if not spec:
		spec = Configspec()
		spec.cfgfile = fname
	with open(fname) as ff:
		yo = yaml.safe_load(ff)
		#print(yo)
		if not yo \
		or 'namespaces' not in yo \
		or 'configvars' not in yo \
		or not yo['namespaces'] \
		or not yo['configvars']:
			sys.stderr.write('Warning: Config file "{0}" missing namespaces or configvars\n'.format(fname))
		else:
			for ns in yo['namespaces']:
				spec.add_namespace(ns)
			for cv in yo['configvars']:
				c = Configvar(cv.get('name'))
				c.set_key(cv.get('key'))
				c.set_namespace(cv.get('namespace'))
				c.set_c_type(cv.get('c_type'))
				c.set_nv_type(cv.get('nv_type'))
				c.set_default(str(cv.get('default')) if cv.get('default') != None else None)
				if 'max_length' in cv:
					c.set_maxsize(cv['max_length'])
				if 'description' in cv:
					c.set_description(cv['description'].strip())
				if 'deprecated' in cv:
					c.set_deprecated(cv['deprecated'])
				if 'cached' in cv:
					c.set_cached(cv['cached'])
#				if 'range' in cv:
#					print('{0}.range={1} {2}'.format(cv['name'], cv['range'], type(cv['range'])))
				spec.add_config(c)
	return spec

configspec = read_config_file(cfgfile)

if not configspec.validate():
	sys.exit(1)
if not args.no_output:
	configspec.generate_c_header(genhfile)
	configspec.generate_c_impl(gencfile, genhfile)
	if (args.desc_file):
		configspec.generate_descriptions(args.desc_file)

